window.DM={"cats":[{"en":"Lungs","nl":"Longen"},{"en":"ENT & Eyes","nl":"KNO & Ogen"},{"en":"Skin","nl":"Huid"},{"en":"Pain & Mobility","nl":"Pijn & Mobiliteit"},{"en":"Nerves & Brain","nl":"Zenuwen & Hersenen"},{"en":"Digestive","nl":"Spijsvertering"},{"en":"Heart & Circulation","nl":"Hart & Bloedsomloop"},{"en":"Autoimmune","nl":"Auto-immuun"},{"en":"Oncology (Adjunct)","nl":"Oncologie (aanvullend)"},{"en":"Veterinary","nl":"Diergeneeskunde"},{"en":"How-To & Safety","nl":"Handleiding & Veiligheid"}],"p":[{"t":"ARDS (adjunct, experimental)","c":0,"en":"Presents DMSO as a hospital-only, experimental add-on for acute respiratory distress, based on older case and animal research into its anti-inflammatory effects. Not intended for home use.","nl":"Experimentele, uitsluitend klinische aanvulling bij acuut longfalen, onderbouwd met oud dier- en casusonderzoek naar ontstekingsremming. Uitdrukkelijk niet voor thuisgebruik."},{"t":"Asthma","c":0,"en":"Covers cautious use of DMSO for asthma, either rubbed on the chest or inhaled in very weak form, to ease tightness alongside regular medication.","nl":"Voorzichtig gebruik bij astma: op de borst smeren of zeer verdund vernevelen om benauwdheid te verlichten, altijd naast de gewone medicatie."},{"t":"Bronchiolitis & Asthma – DMSO Aerosol & Topical Protocol","c":0,"en":"Describes DMSO given as an aerosol or on the skin for bronchiolitis and asthma in children, framed around its anti-inflammatory and mucus-loosening role. Paediatric use needs medical oversight.","nl":"Gaat over DMSO als aerosol of huidmiddel bij bronchiolitis en astma bij kinderen, vanwege de ontstekingsremmende en slijmoplossende werking. Bij kinderen alleen onder medisch toezicht."},{"t":"COPD","c":0,"en":"Outlines weak inhaled DMSO and chest rubs for COPD, said to help breathing and coughing up mucus, and to boost uptake of other inhaled medicines.","nl":"Bij COPD: verdund vernevelen en insmeren van de borst, bedoeld om ademen en ophoesten te vergemakkelijken en andere inhalatiemiddelen beter te laten werken."},{"t":"Cystic fibrosis (adjunct)","c":0,"en":"Mentions scattered reports of DMSO combined with saline or glutathione for cystic fibrosis; stresses that a doctor must supervise.","nl":"Noemt losse meldingen van DMSO samen met zoutoplossing of glutathion bij taaislijmziekte; medisch toezicht is volgens de pagina onmisbaar."},{"t":"Lung Abscess & Pneumonia – Antibiotic Adjunct","c":0,"en":"Frames DMSO as a helper that strengthens antibiotics in lung abscess and pneumonia, citing Russian clinical work. Clinical setting only.","nl":"DMSO als versterker van antibiotica bij longabces en longontsteking, met verwijzing naar Russisch klinisch onderzoek. Alleen in een medische setting."},{"t":"Pneumonia (adjunct)","c":0,"en":"Describes DMSO as a way to help inhaled antimicrobial drugs penetrate in pneumonia, always under supervision.","nl":"Bij longontsteking soms ingezet om vernevelde antimicrobiële middelen beter te laten doordringen; alleen onder begeleiding."},{"t":"Post‑viral cough / bronchitis","c":0,"en":"Suggests short trials of weak inhaled DMSO for lingering cough after a virus or bronchitis, with ordinary comfort measures tried first.","nl":"Voor aanhoudende hoest na een virus of bronchitis: korte proef met verdund vernevelen, maar eerst de gewone huismiddelen."},{"t":"Pulmonary fibrosis (adjunct)","c":0,"en":"Notes anecdotal symptom relief in pulmonary fibrosis from very dilute oral and skin use, while keeping standard treatment.","nl":"Anekdotische klachtenverlichting bij longfibrose via sterk verdunde inname of huidgebruik; de reguliere behandeling blijft gewoon doorlopen."},{"t":"Wildfire smoke / toxic exposure (adjunct)","c":0,"en":"Mentions supportive use for airway irritation after breathing in smoke or toxic fumes.","nl":"Ondersteuning voor geïrriteerde luchtwegen na het inademen van rook of giftige dampen."},{"t":"Cataracts (Adjunct)","c":1,"en":"Covers medically administered DMSO eye drops or eye injections as an add-on for cataract and related eye conditions. Specialist territory.","nl":"Medisch toegediende oogdruppels of injecties met DMSO als aanvulling bij staar en verwante oogaandoeningen. Terrein voor de oogarts."},{"t":"Cavities & Oral Health – DMSO Mouthwash Protocol","c":1,"en":"Describes a homemade mouthwash combining DMSO with hydrogen peroxide and aloe for gum disease, tooth infections and cavities.","nl":"Zelfgemaakt mondwater met DMSO, waterstofperoxide en aloë, bedoeld voor tandvleesproblemen, tandinfecties en gaatjes."},{"t":"Dental Decay & Gum Conditions","c":1,"en":"Discusses DMSO in dental practice for gum problems, deep decay reaching the nerve, and painful dry socket after extraction.","nl":"DMSO in de tandartspraktijk bij tandvleesklachten, cariës tot in de zenuw en een pijnlijke droge tandkas na trekken."},{"t":"Dry eye / ocular surface (adjunct)","c":1,"en":"For dry eye, only extremely weak, eye-safe preparations under a specialist's care are considered.","nl":"Bij droge ogen alleen zeer zwakke, oogvriendelijke preparaten en uitsluitend via een specialist."},{"t":"General Eye Problems – DMSO Eye Drop Protocol","c":1,"en":"Presents daily DMSO eye drops for a range of eye complaints, including declining vision and macular degeneration. Carries a medical caution.","nl":"Dagelijkse DMSO-oogdruppels voor uiteenlopende oogklachten zoals achteruitgang van het zicht en maculadegeneratie. Met medisch voorbehoud."},{"t":"Glaucoma (Adjunct)","c":1,"en":"Frames DMSO as an eye-care add-on for glaucoma that may enhance glaucoma medicines and lower eye pressure, under an eye doctor.","nl":"Aanvulling bij glaucoom die oogdrukverlagers zou versterken en de druk zou verlagen; onder leiding van een oogarts."},{"t":"Hearing loss (adjunct)","c":1,"en":"Notes that some combine DMSO with nutrients for hearing loss, with mixed evidence.","nl":"Sommigen combineren DMSO met voedingsstoffen bij gehoorverlies; het bewijs is wisselend."},{"t":"Macular Degeneration & Retinal Disease (Adjunct)","c":1,"en":"Covers DMSO as an add-on for macular degeneration, retinitis pigmentosa, macular swelling and trauma-related eye inflammation.","nl":"Aanvullende inzet bij maculadegeneratie, retinitis pigmentosa, vochtophoping in de macula en ontsteking na oogletsel."},{"t":"Middle Ear Infections in Children (Adjunct)","c":1,"en":"Describes DMSO helping antibiotics reach the middle ear in children with recurring or hard-to-treat ear infections. Under a doctor.","nl":"DMSO om antibiotica beter in het middenoor te krijgen bij kinderen met terugkerende of hardnekkige oorontsteking. Via de arts."},{"t":"Retinitis Pigmentosa (Adjunct)","c":1,"en":"An add-on approach for retinitis pigmentosa, the progressive retinal disease that narrows side vision.","nl":"Aanvullende aanpak bij retinitis pigmentosa, de voortschrijdende netvliesziekte die het zijzicht vernauwt."},{"t":"Rhinitis / seasonal allergies (adjunct)","c":1,"en":"Reports some relief of nasal irritation in hay fever from very weak use inside the nose.","nl":"Bij hooikoorts melden sommigen minder neusirritatie door zeer verdund gebruik in de neus."},{"t":"Sinusitis (adjunct)","c":1,"en":"Very dilute nasal solutions for sinusitis appear in some protocols; strong mixes on mucous membranes should be avoided.","nl":"Bij bijholteontsteking komen zeer verdunde neusoplossingen voor; sterke mengsels op slijmvlies zijn af te raden."},{"t":"Sinusitis & Sinus Inflammation – DMSO Neti Pot Rinse","c":1,"en":"Describes adding DMSO to a saline neti-pot rinse for acute or chronic sinus infections and allergy-related congestion.","nl":"DMSO toegevoegd aan een neusspoeling met zout water (neti pot) bij acute of chronische sinusitis en allergische klachten."},{"t":"Stye / chalazion","c":1,"en":"For styes and chalazia, very weak application around the eyelid together with warm compresses.","nl":"Bij een strontje of hagelkorrel: zeer zwak rond het ooglid aanbrengen, samen met warme kompressen."},{"t":"Tinnitus – DMSO Ear Drop Protocol","c":1,"en":"Covers ear drops combining DMSO with anti-inflammatory and blood-vessel-widening drugs for tinnitus; prescription medicines are involved.","nl":"Oordruppels waarin DMSO wordt gecombineerd met ontstekingsremmers en vaatverwijders tegen oorsuizen; er zijn receptmiddelen bij betrokken."},{"t":"Tinnitus (adjunct)","c":1,"en":"Mentions applications around the ear for tinnitus comfort, with responses differing from person to person.","nl":"Aanbrengen rondom het oor bij oorsuizen; het effect verschilt sterk per persoon."},{"t":"Acne (adjunct)","c":2,"en":"Positions DMSO as an add-on for acne, alone or with other agents, with a warning to watch for skin drying.","nl":"DMSO als aanvulling bij acne, los of met andere middelen; let op uitdroging van de huid."},{"t":"Anti-Ageing & Scar Healing – DMSO 40% Facial Protocol","c":2,"en":"Describes a DMSO and aloe vera face gel aimed at wrinkles, scars and acne, stressing the right strength for facial skin.","nl":"Gezichtsgel van DMSO en aloë tegen rimpels, littekens en acne, met nadruk op de juiste sterkte voor de gevoelige gezichtshuid."},{"t":"Burns (intact)","c":2,"en":"Covers sprays or solutions for comfort on burns where the skin is unbroken, under supervision.","nl":"Sprays of oplossingen voor verlichting bij brandwonden met intacte huid, onder begeleiding."},{"t":"Chronic ulcers / diabetic foot (adjunct)","c":2,"en":"Describes improved healing of chronic and diabetic foot ulcers when DMSO is used alongside proper wound care.","nl":"Betere genezing van chronische en diabetische voetwonden gemeld wanneer DMSO naast goede wondzorg wordt gebruikt."},{"t":"Club Nails (Overgrown / Deformed Toenails)","c":2,"en":"Covers softening badly thickened, misshapen toenails with DMSO mixed with castor or olive oil.","nl":"Het verzachten van sterk verdikte, vervormde teennagels met DMSO gemengd met ricinus- of olijfolie."},{"t":"Cold sores (adjunct)","c":2,"en":"Refers to the herpes entry: DMSO used as a carrier for antiviral creams on cold sores.","nl":"Verwijst naar herpes: DMSO als drager voor antivirale crèmes bij koortslip."},{"t":"Eczema / atopic dermatitis (cautious)","c":2,"en":"For eczema, only weak DMSO on unbroken skin is considered, with moisturisers remaining the first choice.","nl":"Bij eczeem hooguit zwak DMSO op onbeschadigde huid; vette crèmes blijven de eerste keus."},{"t":"Fungal Toenails – DMSO + Antifungal Protocol","c":2,"en":"Describes DMSO carrying an antifungal drug into infected toenails as a paste. Involves a prescription antifungal.","nl":"DMSO als drager die een schimmeldodend middel in aangetaste teennagels brengt, als pasta. Er is een receptmiddel bij betrokken."},{"t":"Hair Loss & Scalp Problems","c":2,"en":"Covers a scalp lotion with DMSO claimed to encourage hair growth and treat scalp infections.","nl":"Hoofdhuidlotion met DMSO die haargroei zou stimuleren en hoofdhuidinfecties zou aanpakken."},{"t":"Ingrown Toenails","c":2,"en":"For early ingrown toenails, a tiny amount on the inflamed nail fold is said to calm swelling quickly.","nl":"Bij een beginnende ingegroeide teennagel: een heel klein beetje op de ontstoken nagelwal zou de zwelling snel afremmen."},{"t":"Jungle Rot & Chronic Resistant Fungal Skin Infections","c":2,"en":"Describes a DMSO and aloe lotion for stubborn, long-lasting fungal skin infections such as tropical \"jungle rot\".","nl":"Lotion van DMSO en aloë voor hardnekkige, langdurige schimmelinfecties van de huid, zoals tropische 'jungle rot'."},{"t":"Keloids / hypertrophic scars (adjunct)","c":2,"en":"An add-on to silicone and pressure therapy for keloids and raised scars; results vary.","nl":"Aanvulling op siliconen en druktherapie bij keloïd en verdikte littekens; resultaten wisselen."},{"t":"Mature scars / adhesions","c":2,"en":"Describes stronger application on old, settled scars and adhesions to make the tissue more supple.","nl":"Sterkere toepassing op oude, uitgerijpte littekens en verklevingen om het weefsel soepeler te maken."},{"t":"Molluscum contagiosum (adjunct)","c":2,"en":"Notes occasional reported use on molluscum lesions.","nl":"Af en toe gemeld gebruik op waterwratjes (molluscum)."},{"t":"Onychomycosis (fungal nail) adjunct","c":2,"en":"Frames DMSO as helping antifungal medicines penetrate the nail plate in fungal nail infection.","nl":"DMSO als hulpmiddel om schimmelmiddelen door de nagelplaat te laten dringen bij kalknagels."},{"t":"Perioral dermatitis (cautious)","c":2,"en":"For perioral dermatitis, only weak use and avoidance of known triggers.","nl":"Bij rode, schilferige huid rond de mond alleen zwak gebruiken en bekende triggers vermijden."},{"t":"Pressure Ulcers (Bed Sores) – DMSO Early Intervention","c":2,"en":"Covers applying DMSO early to prevent bed sores forming and to speed healing of existing ones.","nl":"Vroegtijdig aanbrengen om doorligwonden te voorkomen en bestaande sneller te laten genezen."},{"t":"Psoriasis (adjunct)","c":2,"en":"Describes variable results in psoriasis, sometimes using DMSO to carry plant-based remedies.","nl":"Wisselende resultaten bij psoriasis; DMSO dient soms als drager voor plantaardige middelen."},{"t":"Radiation dermatitis (intact skin)","c":2,"en":"Comfort support for skin affected by radiotherapy, only where unbroken and with the treatment team's approval.","nl":"Verzachting van door bestraling aangetaste huid, alleen bij intacte huid en met instemming van het behandelteam."},{"t":"Rosacea (cautious)","c":2,"en":"Warns that many rosacea sufferers are sensitive; only very weak use after a test patch.","nl":"Mensen met rosacea zijn vaak gevoelig; alleen heel zwak en na een testplekje."},{"t":"Seborrhoeic dermatitis","c":2,"en":"For seborrhoeic dermatitis, very weak use on small areas together with antifungals.","nl":"Bij seborroïsch eczeem zeer verdund op kleine plekken, samen met schimmelwerende middelen."},{"t":"Sunburn (adjunct)","c":2,"en":"Reports a cooling, soothing effect on sunburn.","nl":"Gemeld als verkoelend en verzachtend bij zonnebrand."},{"t":"Tinea (fungal skin) adjunct","c":2,"en":"Frames DMSO as improving the penetration of antifungals in fungal skin infections.","nl":"Verbetert volgens de pagina de opname van schimmelmiddelen bij huidschimmel."},{"t":"Varicose ulcers (adjunct)","c":2,"en":"Support for pain and healing of venous leg ulcers alongside compression therapy.","nl":"Ondersteuning bij pijn en genezing van open benen door spataderen, naast compressietherapie."},{"t":"Warts / viral lesions","c":2,"en":"Describes focused stronger applications on warts, with neighbouring skin protected.","nl":"Gerichte, sterkere toepassing op wratten, waarbij de omliggende huid beschermd wordt."},{"t":"Achilles & Ankles – DMSO Routine","c":3,"en":"A targeted routine along the Achilles tendon and ankle, following the line from heel to calf.","nl":"Gerichte routine voor achillespees en enkel, van de hiel omhoog richting kuit."},{"t":"Achilles tendinopathy","c":3,"en":"Topical support for Achilles tendon problems, combined with heel-drop strengthening exercises.","nl":"Ondersteuning bij achillespeesklachten, gecombineerd met krachtoefeningen voor de kuit."},{"t":"Acute sprains / strains","c":3,"en":"For fresh sprains and strains, framed as easing pain and swelling and speeding recovery when paired with rehab.","nl":"Bij verstuikingen en verrekkingen: minder pijn en zwelling en sneller herstel, mits samen met revalidatie."},{"t":"Arthritis – DMSO + MSM Joint Gel Protocol","c":3,"en":"A joint protocol layering DMSO with an MSM gel for arthritic and rheumatic joints.","nl":"Gewrichtsprotocol waarbij DMSO en een MSM-gel in lagen worden aangebracht bij artrose en reuma."},{"t":"Arthritis – Mobility & Cartilage Support","c":3,"en":"A skin routine aimed at the grinding, dry-friction feeling in arthritic joints and better joint glide.","nl":"Huidroutine tegen het stroeve, schurende gevoel in artrotische gewrichten, voor soepeler bewegen."},{"t":"Arthritis – Reducing Joint Inflammation","c":3,"en":"A morning and evening routine to calm stiffness, warmth and swelling in inflamed arthritic joints.","nl":"Ochtend- en avondroutine om stijfheid, warmte en zwelling in ontstoken gewrichten te temperen."},{"t":"Back Pain & Sciatica – DMSO + Magnesium Oil Blend","c":3,"en":"Combines DMSO with magnesium oil on the skin for tight backs, sciatica-type pain and stubborn muscle tension.","nl":"DMSO met magnesiumolie op de huid bij een stijve rug, ischiasachtige pijn en hardnekkige spierspanning."},{"t":"Back Pain, Sciatica & Disc Injury – Topical & Compress","c":3,"en":"Skin application plus compresses for low back pain, sciatica-like symptoms and disc-related stiffness.","nl":"Insmeren en kompressen bij lage rugpijn, ischiasklachten en stijfheid door een hernia."},{"t":"Bunions (Hallux Valgus & Acute Bursitis)","c":3,"en":"Topical use on the big-toe joint to calm bunion inflammation and bursitis.","nl":"Aanbrengen op het grote-teengewricht om ontsteking bij een hallux valgus en slijmbeursontsteking te remmen."},{"t":"Bursitis – DMSO 80% Topical Protocol","c":3,"en":"Strong topical DMSO over inflamed bursae in shoulder, hip, elbow or knee, with long-term regular use described.","nl":"Sterk DMSO op ontstoken slijmbeurzen in schouder, heup, elleboog of knie, met nadruk op langdurig volhouden."},{"t":"Carpal tunnel (adjunct)","c":3,"en":"Short-term symptom relief for carpal tunnel, alongside a wrist splint and better ergonomics.","nl":"Tijdelijke verlichting bij carpaletunnelsyndroom, naast een polsspalk en een betere werkhouding."},{"t":"Cervical tension / neck pain","c":3,"en":"Neck pain and tension support, usually combined with gentle mobility exercises.","nl":"Bij nekpijn en spanning, meestal samen met rustige bewegingsoefeningen."},{"t":"Chronic Pain – Nighttime Relief Routine","c":3,"en":"A bedtime routine aimed at easing persistent pain from old injuries, stiffness and deep muscle tension.","nl":"Routine voor het slapengaan tegen aanhoudende pijn door oude blessures, stijfheid en diepe spierspanning."},{"t":"Contusions / haematoma","c":3,"en":"Reported to soothe bruises and help them clear faster.","nl":"Zou kneuzingen en bloeduitstortingen verzachten en sneller laten wegtrekken."},{"t":"Costochondritis","c":3,"en":"Soothing application over the tender rib-cartilage joints in costochondritis.","nl":"Verzachtend aanbrengen op de pijnlijke overgang van rib naar borstbeen (syndroom van Tietze)."},{"t":"CRPS (adjunct)","c":3,"en":"Explored for nerve pain and skin changes in complex regional pain syndrome; results vary.","nl":"Onderzocht bij zenuwpijn en huidveranderingen bij CRPS (posttraumatische dystrofie); wisselende uitkomsten."},{"t":"Dislocations – Post-Reduction Recovery","c":3,"en":"Use after a dislocated joint has been put back, to reduce leftover pain and swelling.","nl":"Na het terugzetten van een ontwricht gewricht, om resterende pijn en zwelling te verminderen."},{"t":"Elbow – Tendon Support","c":3,"en":"An elbow routine following the tendon lines on the outer and inner sides of the joint.","nl":"Elleboogroutine langs de peeslijnen aan de buiten- en binnenkant van het gewricht."},{"t":"Fallen Arches (Pes Planus)","c":3,"en":"DMSO combined with ultrasound as the first step of a podiatry approach to flat feet.","nl":"DMSO met ultrageluid als eerste stap in een podotherapeutische aanpak van platvoeten."},{"t":"Fibromyalgia – Herbal Anti-Inflammatory Synergy","c":3,"en":"Layers DMSO with herbal preparations such as arnica or turmeric for broader relief in fibromyalgia.","nl":"DMSO in lagen met kruidenpreparaten als arnica of kurkuma voor bredere verlichting bij fibromyalgie."},{"t":"Fibromyalgia – Nervous System Support","c":3,"en":"Frames topical DMSO as calming overactive nerves in fibromyalgia and chronic pain.","nl":"Presenteert DMSO op de huid als middel om overprikkelde zenuwen te kalmeren bij fibromyalgie en chronische pijn."},{"t":"Fracture Recovery – DMSO Adjunct","c":3,"en":"Topical use after a fracture has been immobilised, to reduce swelling and help regain movement.","nl":"Na het fixeren van een botbreuk aanbrengen om zwelling te beperken en de beweeglijkheid terug te winnen."},{"t":"Frozen shoulder (adhesive capsulitis)","c":3,"en":"Support for frozen shoulder during range-of-motion rehab; progress is described as slow.","nl":"Ondersteuning bij een frozen shoulder tijdens bewegingsrevalidatie; vooruitgang gaat langzaam."},{"t":"Frozen Shoulder (Adhesive Capsulitis)","c":3,"en":"Strong topical DMSO over a frozen shoulder, aimed at stiffness and adhesions.","nl":"Sterk DMSO op de schouder bij een frozen shoulder, gericht op stijfheid en verklevingen."},{"t":"Gout","c":3,"en":"Topical use on acutely inflamed gout joints such as the big toe, ankle and knee.","nl":"Aanbrengen op acuut ontstoken jichtgewrichten zoals grote teen, enkel en knie."},{"t":"Hammertoes","c":3,"en":"Applied to hammertoes to relieve pain from the bent, corn-prone toe.","nl":"Op hamertenen om pijn van de kromme, likdoorngevoelige teen te verlichten."},{"t":"Hands & Fingers – Roll-On Routine","c":3,"en":"A careful roll-on routine for knuckles and finger joints.","nl":"Nauwkeurige roller-routine voor knokkels en vingergewrichten."},{"t":"Heel Spurs (Calcaneal Spur)","c":3,"en":"Topical use plus an occlusive wrap on the heel for inflamed heel spurs.","nl":"Aanbrengen op de hiel met een afsluitend verband bij een ontstoken hielspoor."},{"t":"Hip osteoarthritis","c":3,"en":"Pain support for hip osteoarthritis alongside walking and strength training.","nl":"Pijnondersteuning bij heupartrose naast loop- en krachttraining."},{"t":"IT band syndrome","c":3,"en":"Local application for IT band syndrome, together with hip strengthening.","nl":"Plaatselijk aanbrengen bij het ITB-syndroom (lopersknie), samen met heupversterking."},{"t":"Knee osteoarthritis","c":3,"en":"Relief of pain and stiffness in knee osteoarthritis, combined with exercise.","nl":"Verlichting van pijn en stijfheid bij knieartrose, gecombineerd met beweging."},{"t":"Knees – Daily Relief Routine","c":3,"en":"An end-of-day knee routine built on precise, consistent application.","nl":"Dagelijkse avondroutine voor de knieën, gericht op nauwkeurig en regelmatig aanbrengen."},{"t":"Knees – Post-Activity Care","c":3,"en":"Knee care right after exercise, while the tissues are still warm.","nl":"Kniezorg direct na het sporten, terwijl het weefsel nog warm is."},{"t":"Knees – Sleep-Support Nighttime Routine","c":3,"en":"A night-time routine for knee discomfort that disturbs sleep, including the surrounding calf muscles.","nl":"Avondroutine voor kniepijn die de slaap verstoort, inclusief de omliggende kuitspieren."},{"t":"Lateral epicondylitis (tennis elbow)","c":3,"en":"Support for tennis elbow, together with eccentric strengthening.","nl":"Ondersteuning bij tenniselleboog, samen met excentrische krachtoefeningen."},{"t":"Low back pain (muscular)","c":3,"en":"A comfort add-on for muscular low back pain alongside mobility work.","nl":"Verlichtende aanvulling bij spierpijn in de onderrug, naast bewegingsoefeningen."},{"t":"Lower Back – Targeted Application Protocol","c":3,"en":"A structured lumbar routine using horizontal strokes across the lower back.","nl":"Gestructureerde routine voor de onderrug met horizontale strijkbewegingen."},{"t":"Lower Body vs Upper Body – Tailored DMSO Application Routines","c":3,"en":"Explains how to adapt technique for the lower versus the upper body.","nl":"Legt uit hoe je de techniek aanpast voor onderlichaam versus bovenlichaam."},{"t":"Medial epicondylitis (golfer’s elbow)","c":3,"en":"Focused application on the inner elbow for golfer's elbow.","nl":"Gerichte toepassing aan de binnenkant van de elleboog bij golferselleboog."},{"t":"Metatarsalgia (Morton's Toe)","c":3,"en":"DMSO as a carrier for local anaesthetic injections in forefoot pain; a medical procedure.","nl":"DMSO als drager bij verdovingsinjecties tegen pijn in de voorvoet; een medische ingreep."},{"t":"Mid & Upper Back – DMSO Routine","c":3,"en":"A routine for the mid and upper back, the area that holds postural and stress tension.","nl":"Routine voor midden- en bovenrug, waar houdings- en stressspanning zich ophoopt."},{"t":"Muscle Recovery – Post-Exercise","c":3,"en":"A post-workout routine for muscle recovery, applied when the skin is warm and receptive.","nl":"Routine na de training voor spierherstel, aangebracht als de huid nog warm is."},{"t":"Muscle Repair & Wasting – DMSO + L-Glutamine + MSM Protocol","c":3,"en":"Combines DMSO with L-glutamine and MSM for muscle injury and muscle wasting.","nl":"DMSO samen met L-glutamine en MSM bij spierletsel en spierafbraak."},{"t":"Muscle Strains & Tension Areas","c":3,"en":"A flexible routine for strain-prone spots like neck, shoulders, lower back and hamstrings.","nl":"Flexibele routine voor blessuregevoelige plekken als nek, schouders, onderrug en hamstrings."},{"t":"Neck – Blended DMSO Compress","c":3,"en":"A calm, meditative neck compress using a cloth moistened with a DMSO blend.","nl":"Rustgevend nekkompres met een doek bevochtigd met een DMSO-mengsel."},{"t":"Neck – Digital Strain Protocol","c":3,"en":"Aimed at \"tech neck\", the tightness at the skull base from screen use.","nl":"Gericht op de 'beeldschermnek': spanning aan de schedelbasis door veel schermgebruik."},{"t":"Osteoarthritis – DMSO + MSM + Vitamins D & K2 Protocol","c":3,"en":"An osteoarthritis plan combining skin DMSO with oral MSM and vitamins D and K2.","nl":"Artroseplan met DMSO op de huid plus MSM en vitamine D en K2 via de mond."},{"t":"Osteomyelitis (Bone Infection) – DMSO + Antibiotic","c":3,"en":"Intravenous DMSO with antibiotics for bone infection; strictly a hospital treatment.","nl":"DMSO via een infuus samen met antibiotica bij botinfectie; puur een ziekenhuisbehandeling."},{"t":"Patellar tendinopathy","c":3,"en":"Support for jumper's knee alongside isometric and eccentric training.","nl":"Ondersteuning bij springersknie naast isometrische en excentrische training."},{"t":"Phantom Limb Pain","c":3,"en":"A lotion with DMSO, capsicum and aloe on the amputation site for phantom pain.","nl":"Lotion met DMSO, capsicum en aloë op de amputatieplek tegen fantoompijn."},{"t":"Plantar fasciitis","c":3,"en":"An add-on for the morning heel pain and stiffness of plantar fasciitis.","nl":"Aanvulling bij de ochtendpijn en stijfheid van fasciitis plantaris."},{"t":"Post-Surgical Pain Management","c":3,"en":"Topical DMSO around surgical wounds for pain after an operation; involves medical oversight.","nl":"DMSO rond operatiewonden tegen pijn na een ingreep; vraagt medische afstemming."},{"t":"Shin splints (MTSS)","c":3,"en":"Reduced training load plus local application for shin splints.","nl":"Minder belasting plus plaatselijk aanbrengen bij scheenbeenvliesontsteking."},{"t":"Shoulder impingement / rotator cuff","c":3,"en":"Topical use over the shoulder during rehab for impingement or rotator cuff problems.","nl":"Op de schouder tijdens revalidatie bij inklemming of rotatorcuffklachten."},{"t":"Shoulder Tendons – Focused DMSO Care","c":3,"en":"A shoulder-tendon routine using curved strokes that follow the joint.","nl":"Schouderpeesroutine met gebogen strijkbewegingen die het gewricht volgen."},{"t":"Shoulders – Heat & Cold Pairing","c":3,"en":"Pairs shoulder application with warm and cold cloths to enhance the effect.","nl":"Combineert aanbrengen op de schouder met warme en koude doeken voor meer effect."},{"t":"Shoulders – Targeted Application","c":3,"en":"Precise application over the upper trapezius and deltoid region.","nl":"Precies aanbrengen op de bovenste monnikskapspier en de deltaspier."},{"t":"Tendinitis – High-Concentration DMSO Protocol (80–90%)","c":3,"en":"Very strong DMSO over inflamed tendons in shoulder, elbow, wrist or knee; skin tolerance is a concern.","nl":"Zeer sterk DMSO op ontstoken pezen in schouder, elleboog, pols of knie; let op huidverdraagzaamheid."},{"t":"Tendonitis / bursitis (shoulder/elbow/hip)","c":3,"en":"Local applications to ease tendon or bursa pain at common sites like shoulder, elbow and hip.","nl":"Plaatselijk aanbrengen bij pees- of slijmbeurspijn in schouder, elleboog en heup."},{"t":"Trigger finger (tenosynovitis)","c":3,"en":"Focused application over the affected finger tendon in trigger finger.","nl":"Gericht aanbrengen op de aangedane vingerpees bij een triggervinger."},{"t":"Anxiety & Obsessive-Compulsive Disorder – DMSO Adjunct","c":4,"en":"Describes DMSO injections as a historical add-on for severe anxiety and OCD; strictly a medical treatment.","nl":"Beschrijft DMSO-injecties als historische aanvulling bij ernstige angst en dwangstoornis; puur medische behandeling."},{"t":"Concussion / head injury (adjunct)","c":4,"en":"Cites older protocols on membrane protection after concussion or head injury; supervision required.","nl":"Verwijst naar oudere protocollen over celbescherming na hersenschudding of hoofdletsel; toezicht vereist."},{"t":"Diabetes – Circulation & Amputation Prevention","c":4,"en":"Topical and oral DMSO for poor circulation and nerve damage in diabetes, framed as helping prevent amputation.","nl":"DMSO via huid en mond bij slechte doorbloeding en zenuwschade door diabetes, gepresenteerd als hulp om amputatie te voorkomen."},{"t":"Down Syndrome – DMSO + Amino Acid Therapy","c":4,"en":"Reports a Chilean study pairing DMSO with amino acid injections in Down syndrome; experimental medical use.","nl":"Noemt een Chileens onderzoek met DMSO en aminozuurinjecties bij downsyndroom; experimenteel en medisch."},{"t":"Hemorrhagic & Embolic Stroke (Emergency Adjunct)","c":4,"en":"Intravenous DMSO as an emergency add-on for both bleeding and clot-related stroke; hospital only.","nl":"DMSO via infuus als noodaanvulling bij zowel hersenbloeding als herseninfarct; alleen in het ziekenhuis."},{"t":"Intracranial Hypertension (Head Injury Adjunct)","c":4,"en":"Intravenous DMSO to lower dangerous brain pressure after head injury, in intensive care.","nl":"DMSO via infuus om gevaarlijk hoge hersendruk na hoofdletsel te verlagen, op de intensive care."},{"t":"Manic Depression & Alcoholic Psychosis – DMSO Adjunct","c":4,"en":"Historical intramuscular DMSO as an add-on for mania and alcohol-related psychosis.","nl":"Historische spierinjecties met DMSO als aanvulling bij manie en alcoholpsychose."},{"t":"Migraine/neck tension (adjunct)","c":4,"en":"Some report relief from applying around the neck for migraine and neck tension.","nl":"Sommigen melden verlichting door rond de nek aan te brengen bij migraine en nekspanning."},{"t":"Multiple Sclerosis (Adjunct)","c":4,"en":"Presents DMSO as an add-on in MS, citing favourable immune effects.","nl":"DMSO als aanvulling bij MS, met verwijzing naar gunstige effecten op het afweersysteem."},{"t":"Myasthenia Gravis (Adjunct)","c":4,"en":"Claims DMSO lowered the abnormal antibodies in myasthenia gravis in research; medical context.","nl":"Stelt dat DMSO in onderzoek de afwijkende antistoffen bij myasthenie verlaagde; medische context."},{"t":"Peripheral neuropathy (adjunct)","c":4,"en":"Support for burning and tingling in nerve damage, together with nutritional support.","nl":"Ondersteuning bij branderige en tintelende zenuwpijn, samen met voedingsstoffen."},{"t":"Post‑herpetic neuralgia","c":4,"en":"Topical use for nerve pain lingering after shingles.","nl":"Op de huid bij zenuwpijn die na gordelroos blijft hangen."},{"t":"Restless Leg Syndrome – DMSO + Magnesium Evening Protocol","c":4,"en":"Evening application to legs and feet, combined with magnesium, for restless legs.","nl":"Avondlijk insmeren van benen en voeten, gecombineerd met magnesium, bij rusteloze benen."},{"t":"Schizophrenia (Acute) – DMSO Injection Protocol","c":4,"en":"Reports a Peruvian study of intramuscular DMSO in acute schizophrenia; purely clinical.","nl":"Noemt Peruaans onderzoek met spierinjecties DMSO bij acute schizofrenie; uitsluitend klinisch."},{"t":"Sciatic nerve irritation (adjunct)","c":4,"en":"Topical use along the buttock and back of the thigh for sciatic irritation, with mobility work.","nl":"Langs bil en achterkant dijbeen bij geïrriteerde heupzenuw, samen met bewegen."},{"t":"Senile Dementia & Alzheimer's – DMSO Adjunct","c":4,"en":"Historical DMSO therapies with amino acids or circulation drugs for dementia and Alzheimer's.","nl":"Historische DMSO-therapieën met aminozuren of vaatmiddelen bij dementie en alzheimer."},{"t":"Spinal Cord Injury – Emergency DMSO Protocol","c":4,"en":"Emergency intravenous DMSO soon after a spinal cord injury to limit damage; hospital only.","nl":"Spoedinfuus met DMSO kort na een dwarslaesie om schade te beperken; alleen in het ziekenhuis."},{"t":"Temporal Arteritis (Adjunct)","c":4,"en":"Topical use on forehead and neck as an add-on for temporal arteritis, alongside medical care.","nl":"Op voorhoofd en nek als aanvulling bij arteriitis temporalis (reuscelarteriitis), naast medische zorg."},{"t":"Trigeminal neuralgia (adjunct)","c":4,"en":"Very cautious application around the face for trigeminal nerve pain.","nl":"Zeer voorzichtig rond het gezicht aanbrengen bij aangezichtszenuwpijn."},{"t":"Anal fissure (adjunct)","c":5,"en":"Weak application around the anus for fissure comfort, keeping it off the tear itself.","nl":"Zwak rond de anus voor verlichting bij een fissuur, maar niet op het scheurtje zelf."},{"t":"Cirrhosis of the Liver (Adjunct)","c":5,"en":"Oral DMSO in aloe juice as an add-on for liver cirrhosis, citing one study.","nl":"DMSO in aloëvera-sap via de mond als aanvulling bij levercirrose, op basis van één onderzoek."},{"t":"Cryopreservation (cells/tissue)","c":5,"en":"Explains DMSO's long-standing lab and clinic role in freezing cells and tissue.","nl":"Legt de vaste rol van DMSO uit bij het invriezen van cellen en weefsel in lab en kliniek."},{"t":"Duodenal Ulcers – DMSO Oral Protocol","c":5,"en":"Oral DMSO in aloe juice for healing duodenal ulcers and preventing relapse.","nl":"DMSO in aloësap via de mond voor het genezen van een twaalfvingerdarmzweer en het voorkomen van terugval."},{"t":"Dysmenorrhoea (adjunct)","c":5,"en":"Application to the lower belly on days with menstrual cramps.","nl":"Op de onderbuik aanbrengen op dagen met menstruatiekrampen."},{"t":"Endometriosis (adjunct)","c":5,"en":"Topical comfort on the abdomen for endometriosis pain.","nl":"Verlichting op de buik bij pijn door endometriose."},{"t":"Gallstones – Dissolution Adjunct","c":5,"en":"DMSO as a dissolving aid in medical treatment of gallstones.","nl":"DMSO als oplossend hulpmiddel bij de medische behandeling van galstenen."},{"t":"Gastritis / peptic ulcer (adjunct)","c":5,"en":"Mentions old dilute oral protocols for gastritis and ulcers, urging a talk about the risks.","nl":"Noemt oude verdunde orale protocollen bij maagontsteking en maagzweer; bespreek eerst de risico's."},{"t":"Haemorrhoids – DMSO + Witch Hazel Protocol","c":5,"en":"Topical DMSO with witch hazel and herbal support for haemorrhoids.","nl":"DMSO op de huid met hamamelis en kruiden bij aambeien."},{"t":"Haemorrhoids (adjunct)","c":5,"en":"Weak to moderate application alongside standard measures for haemorrhoids.","nl":"Zwak tot matig aanbrengen naast de gewone maatregelen bij aambeien."},{"t":"IBS abdominal wall pain (adjunct)","c":5,"en":"Application on tender spots of the belly wall in IBS-related pain.","nl":"Aanbrengen op gevoelige plekken van de buikwand bij pijn door prikkelbare darm."},{"t":"Interstitial cystitis (RIMSO‑50)","c":5,"en":"Describes the officially approved bladder instillation of DMSO for interstitial cystitis, given by a urologist.","nl":"Beschrijft de officieel goedgekeurde blaasspoeling met DMSO bij interstitiële cystitis, door de uroloog."},{"t":"Intestinal Fungal Blockage","c":5,"en":"Oral DMSO in aloe juice for a gut fungal infection causing partial blockage.","nl":"DMSO in aloësap via de mond bij een darmschimmel die een gedeeltelijke verstopping geeft."},{"t":"Medical devices/solvent (Onyx, Tegress, Viadur)","c":5,"en":"Notes DMSO's role as a solvent in several approved medical products.","nl":"Wijst op DMSO als oplosmiddel in diverse goedgekeurde medische producten."},{"t":"NSAID-Induced Gastritis – DMSO Treatment","c":5,"en":"Oral DMSO to heal stomach damage caused by painkillers such as NSAIDs.","nl":"DMSO via de mond om maagschade door pijnstillers zoals NSAID's te herstellen."},{"t":"Stress-Induced Gastric Mucosal Injury","c":5,"en":"DMSO to prevent and treat stress-related stomach lining damage in critically ill patients; hospital use.","nl":"DMSO tegen stressschade aan het maagslijmvlies bij ernstig zieke patiënten; ziekenhuisgebruik."},{"t":"Transdermal carrier","c":5,"en":"Explains DMSO's ability to carry other substances through the skin, so cleanliness matters.","nl":"Legt uit dat DMSO andere stoffen door de huid meeneemt, waardoor schoon werken essentieel is."},{"t":"Urinary Tract Conditions (Non-IC)","c":5,"en":"Covers urinary tract complaints beyond interstitial cystitis, like urethral pain.","nl":"Gaat over urinewegklachten buiten interstitiële cystitis, zoals pijn in de plasbuis."},{"t":"Angina Pectoris & Heart Attack (Adjunct)","c":6,"en":"Describes South American research on DMSO as a cardiac add-on in heart attack and angina; strictly medical.","nl":"Zuid-Amerikaans onderzoek naar DMSO als hartaanvulling bij infarct en angina pectoris; puur medisch."},{"t":"Pernio / chilblains","c":6,"en":"Comfort for chilblains caused by cold-induced blood vessel spasm.","nl":"Verlichting bij wintertenen door vaatkramp in de kou."},{"t":"Raynaud‑type symptoms (adjunct)","c":6,"en":"Some find comfort in fingers and toes with Raynaud-type symptoms.","nl":"Sommigen ervaren verlichting in vingers en tenen bij Raynaud-achtige klachten."},{"t":"Varicose veins (skin comfort)","c":6,"en":"Only soothes the skin over varicose veins; does not treat the veins themselves.","nl":"Verzacht alleen de huid boven spataderen; de aderen zelf worden niet behandeld."},{"t":"Amyloidosis (Adjunct)","c":7,"en":"Oral and topical DMSO as an add-on for secondary amyloidosis, the build-up of abnormal proteins; medical context.","nl":"DMSO via mond en huid als aanvulling bij secundaire amyloïdose, de ophoping van afwijkende eiwitten; medische context."},{"t":"Ankylosing Spondylitis","c":7,"en":"Topical use along the spine for ankylosing spondylitis (Bechterew).","nl":"Aanbrengen langs de wervelkolom bij de ziekte van Bechterew."},{"t":"Bacterial skin infections (adjunct)","c":7,"en":"Helps topical antibiotics and antiseptics penetrate in bacterial skin infections.","nl":"Helpt antibiotica en ontsmettingsmiddelen beter door te dringen bij bacteriële huidinfecties."},{"t":"Chronic Inflammation – Daily Topical Management","c":7,"en":"A twice-daily routine aimed at recurring inflammation hotspots.","nl":"Routine van twee keer per dag voor terugkerende ontstekingsplekken."},{"t":"Cold Sores & Post-Herpetic Neuralgia – DMSO + Colloidal Silver","c":7,"en":"Pairs DMSO with colloidal silver for cold sores, shingles and post-shingles nerve pain.","nl":"DMSO met colloïdaal zilver bij koortslip, gordelroos en zenuwpijn daarna."},{"t":"Fungal nail (onychomycosis) adjunct","c":7,"en":"Same idea as the skin entry: DMSO helps antifungals into the nail.","nl":"Zelfde idee als bij Huid: DMSO helpt schimmelmiddelen de nagel in."},{"t":"Fungal skin (tinea) adjunct","c":7,"en":"Penetration aid for antifungal creams in fungal skin infections.","nl":"Hulpmiddel om schimmelcrèmes beter te laten opnemen bij huidschimmel."},{"t":"Herpes labialis / shingles (adjunct)","c":7,"en":"An antiviral helper and carrier for cold sores and shingles that also eases discomfort.","nl":"Hulp en drager voor antivirale middelen bij koortslip en gordelroos, die ook het ongemak vermindert."},{"t":"Infections – DMSO + Antibiotic Synergy Protocol","c":7,"en":"DMSO alongside antibiotics for infections that resist standard treatment; prescribed drugs involved.","nl":"DMSO naast antibiotica bij infecties die niet op gewone behandeling reageren; er zijn receptmiddelen bij betrokken."},{"t":"Lupus – Weekly Injection & Topical Maintenance Protocol","c":7,"en":"A weekly DMSO and vitamin injection plus daily lotion for long-term lupus management; needs a medical professional.","nl":"Wekelijkse injectie met DMSO en vitaminen plus dagelijkse lotion bij lupus op lange termijn; vereist een zorgprofessional."},{"t":"Lupus Erythematosus (Adjunct)","c":7,"en":"An add-on in systemic lupus, mainly for lupus-related skin problems.","nl":"Aanvulling bij systemische lupus, vooral voor huidklachten."},{"t":"Scleroderma (Progressive Systemic Sclerosis)","c":7,"en":"Topical or oral DMSO in scleroderma, aimed at small-nerve pain and slow-healing ulcers.","nl":"DMSO op de huid of via de mond bij sclerodermie, tegen pijn in kleine zenuwen en slecht genezende wondjes."},{"t":"Sinus infections (adjunct)","c":7,"en":"Points to the sinusitis entries and advises medical review.","nl":"Verwijst naar de sinusitis-items en raadt medische beoordeling aan."},{"t":"Cancer – DMSO-Hematoxylon Protocol (Historic)","c":8,"en":"Recounts a historic cancer treatment combining DMSO with hematoxylon, used by one Houston doctor; not current practice.","nl":"Vertelt over een historische kankerbehandeling met DMSO en hematoxyline van een arts in Houston; geen huidige praktijk."},{"t":"Chemo potentiation / tissue protection (historic)","c":8,"en":"Historical research into DMSO as a booster for chemotherapy or a protector of healthy tissue.","nl":"Historisch onderzoek naar DMSO als versterker van chemo of als bescherming van gezond weefsel."},{"t":"Leukaemia – DMSO Cell Differentiation (Adjunct)","c":8,"en":"Describes lab findings that DMSO can make leukaemia cells mature; research context only.","nl":"Beschrijft labbevindingen dat DMSO leukemiecellen kan laten uitrijpen; alleen onderzoekscontext."},{"t":"Radiation protection (historic)","c":8,"en":"Historical exploration of DMSO's antioxidant role in protection against radiation.","nl":"Historisch onderzoek naar de antioxiderende rol van DMSO als stralingsbescherming."},{"t":"Topical vitamin C mixes for skin lesions (experimental)","c":8,"en":"Experimental vitamin C mixtures for skin lesions, based only on case reports; specialist supervision required.","nl":"Experimentele mengsels met vitamine C voor huidafwijkingen, alleen op basis van casussen; begeleiding door een specialist vereist."},{"t":"Canine otitis (Synotic®)","c":9,"en":"Notes veterinary ear medicines for dogs that contain DMSO.","nl":"Noemt diergeneeskundige oormiddelen voor honden waar DMSO in zit."},{"t":"Equine swelling and soft‑tissue injuries","c":9,"en":"Notes licensed veterinary DMSO products for swelling and soft-tissue injuries in horses.","nl":"Noemt geregistreerde DMSO-producten voor zwellingen en wekedelenletsel bij paarden."},{"t":"30-Day Transformation Programme","c":10,"en":"A four-week programme building up week by week, from technique to mobility and beyond.","nl":"Programma van vier weken dat per week opbouwt, van techniek naar mobiliteit en verder."},{"t":"7-Day Relief Plan – Daily Protocol","c":10,"en":"A one-week daily checklist covering clean application, hydration and movement.","nl":"Dagelijkse checklist voor één week: schoon aanbrengen, voldoende drinken en bewegen."},{"t":"Aloe Vera as a DMSO Carrier – Blends, Ratios & Use","c":10,"en":"A guide to using aloe vera gel as a base for DMSO and choosing a good aloe.","nl":"Gids voor aloëvera-gel als basis voor DMSO en het kiezen van een goede aloë."},{"t":"Application materials","c":10,"en":"Advises simple, clean tools and avoiding plastics that DMSO can attack.","nl":"Raadt eenvoudige, schone hulpmiddelen aan en kunststoffen die DMSO aantast te vermijden."},{"t":"Application Methods – Topical Rubbing, Compresses, Soaks, Sprays & Layering","c":10,"en":"Overview of the main methods: rubbing in, compresses, soaks, sprays and layering.","nl":"Overzicht van de methodes: inwrijven, kompressen, baden, sprays en in lagen werken."},{"t":"Arnica + DMSO – Herbal Pairing for Bruises, Strains & Overworked Tissue","c":10,"en":"How to pair alcohol-free arnica gel with DMSO for bruises and overworked muscles.","nl":"Hoe je alcoholvrije arnicagel met DMSO combineert bij blauwe plekken en overbelaste spieren."},{"t":"Calendula + DMSO – Gentle Herbal Pairing for Stressed or Irritated Skin","c":10,"en":"Pairing calendula oil or water with DMSO for irritated or stressed skin.","nl":"Calendula-olie of -water samen met DMSO voor geïrriteerde of gestreste huid."},{"t":"Choosing Quality DMSO – Purity Grades & What to Look For","c":10,"en":"Explains purity grades of DMSO and what to look for when buying.","nl":"Legt de zuiverheidsgraden van DMSO uit en waar je bij aankoop op let."},{"t":"Combining with other agents","c":10,"en":"Warns that DMSO drags along whatever is on the skin, so choose companions carefully.","nl":"Waarschuwt dat DMSO alles meeneemt wat op de huid zit; kies combinaties dus zorgvuldig."},{"t":"Detox Support – Daily DMSO Routine","c":10,"en":"A morning-to-evening routine framed as supporting natural detox and the lymph system.","nl":"Dagroutine van ochtend tot avond, gepresenteerd als steun voor natuurlijke ontgifting en de lymfe."},{"t":"Diluting DMSO Correctly – Ratios, Steps & Safe Mixing","c":10,"en":"A general guide on why and how to dilute DMSO and which liquids to use.","nl":"Algemene uitleg waarom en hoe je DMSO verdunt en met welke vloeistoffen."},{"t":"Dilution & concentration guide","c":10,"en":"Explains matching strength to skin thickness and sensitivity.","nl":"Legt uit dat de sterkte moet passen bij huiddikte en gevoeligheid."},{"t":"DIY DMSO Roll-Ons, Sprays & Compresses – How to Prepare Your Own","c":10,"en":"How to prepare your own roll-ons, sprays and compresses.","nl":"Hoe je zelf rollers, sprays en kompressen klaarmaakt."},{"t":"DMSO + Castor Oil – Layering for Deep Sustained Support","c":10,"en":"Using DMSO and castor oil one after another, not premixed, for deep support.","nl":"DMSO en ricinusolie na elkaar gebruiken, niet vooraf gemengd, voor diepere werking."},{"t":"DMSO + Castor Oil Combination Protocol","c":10,"en":"Combines DMSO with hexane-free castor oil for rheumatic pain, scars and tendon problems.","nl":"DMSO met hexaanvrije ricinusolie bij reumatische pijn, littekens en peesklachten."},{"t":"DMSO + CBD Oil Combination – Pain & Nervous System Support","c":10,"en":"Pairs CBD oil with DMSO for pain, tension and nervous-system calm.","nl":"CBD-olie gecombineerd met DMSO bij pijn, spanning en een onrustig zenuwstelsel."},{"t":"DMSO + Colloidal Silver Combination – Infection Protocol","c":10,"en":"Combines colloidal silver with DMSO as a claimed antibacterial and antifungal mix.","nl":"Colloïdaal zilver met DMSO als veronderstelde bacterie- en schimmelremmende combinatie."},{"t":"DMSO + Essential Oil Combinations Guide","c":10,"en":"How DMSO greatly increases skin absorption of essential oils, which calls for caution.","nl":"DMSO verhoogt de opname van etherische oliën sterk via de huid, dus voorzichtigheid is nodig."},{"t":"DMSO + MSM Combined Internal Protocol","c":10,"en":"Taking DMSO and MSM together internally for systemic sulphur support.","nl":"DMSO en MSM samen innemen voor ondersteuning met zwavel van binnenuit."},{"t":"DMSO + Vitamin C Cancer Prevention Protocol","c":10,"en":"An author's preventive plan pairing oral DMSO with buffered vitamin C; framed as prevention, not treatment.","nl":"Preventieplan van een auteur met DMSO via de mond en gebufferde vitamine C; als preventie gebracht, niet als behandeling."},{"t":"DMSO as a Carrier Agent – What Can & Cannot Be Used","c":10,"en":"Explains the carrier effect and which companion ingredients are and aren't suitable.","nl":"Legt het drager-effect uit en welke combinaties wel en niet geschikt zijn."},{"t":"DMSO Concentrations Guide – What Strength to Use","c":10,"en":"Guidance on choosing a suitable strength per body area and complaint.","nl":"Richtlijnen voor de passende sterkte per lichaamsdeel en klacht."},{"t":"DMSO Formats – Liquid vs Gel vs Roll-On","c":10,"en":"Compares liquid, gel and roll-on forms and their pros and cons.","nl":"Vergelijkt vloeistof, gel en roller met hun voor- en nadelen."},{"t":"DMSO Odour Management – Wintergreen & Hydrogen Peroxide Methods","c":10,"en":"Advanced tips for reducing DMSO's odour, using wintergreen or peroxide methods.","nl":"Geavanceerde tips tegen de DMSO-geur, met wintergreen of waterstofperoxide."},{"t":"DMSO Storage & Shelf Life","c":10,"en":"How to store DMSO to keep it pure and stable: temperature, light and containers.","nl":"Hoe je DMSO zuiver en stabiel bewaart: temperatuur, licht en verpakking."},{"t":"Healing Crisis & Detoxification Reactions – Management Guide","c":10,"en":"How to recognise and handle a \"healing crisis\" or detox reaction after starting.","nl":"Hoe je een 'genezingscrisis' of ontgiftingsreactie na de start herkent en opvangt."},{"t":"Hydrosols & Distilled Water as DMSO Carriers","c":10,"en":"Using hydrosols and distilled water as light, clean bases for DMSO.","nl":"Hydrolaten en gedestilleerd water als lichte, schone basis voor DMSO."},{"t":"Hygiene & Application Rules – The Clean Application Mindset","c":10,"en":"The full hygiene framework: preparing the skin, clean hands and tools.","nl":"Het complete hygiënekader: huid voorbereiden, schone handen en materialen."},{"t":"Magnesium Oil as a DMSO Carrier – Blends, Ratios & Muscle Support","c":10,"en":"Pairing magnesium oil with DMSO for muscle support.","nl":"Magnesiumolie samen met DMSO voor ondersteuning van de spieren."},{"t":"Maintaining DMSO Results Long-Term","c":10,"en":"How to keep the gains once a structured DMSO routine is finished.","nl":"Hoe je de resultaten vasthoudt nadat een vaste DMSO-routine is afgerond."},{"t":"Managing the DMSO Garlic-Like Odour","c":10,"en":"Why DMSO causes a garlic-like smell and practical ways to limit it.","nl":"Waarom DMSO een knoflookachtige geur geeft en hoe je die beperkt."},{"t":"Natural Antihistamine for DMSO Reactions","c":10,"en":"A simple natural remedy for itching or hives as a reaction to DMSO.","nl":"Een eenvoudig natuurlijk middel tegen jeuk of bultjes als reactie op DMSO."},{"t":"Nebulising precautions","c":10,"en":"Precautions for inhalation: only extremely weak in saline, and some devices may be damaged.","nl":"Voorzorgen bij vernevelen: alleen extreem verdund in zoutoplossing, en sommige apparaten kunnen beschadigen."},{"t":"Oral use basics","c":10,"en":"Oral use only very dilute, expect taste and odour, and consult a clinician first.","nl":"Innemen alleen sterk verdund; reken op smaak en geur en overleg eerst met een arts."},{"t":"Overuse Response & Skin Reset Protocol","c":10,"en":"What to do when too much has been applied and how to let the skin recover.","nl":"Wat te doen bij te veel aanbrengen en hoe je de huid laat herstellen."},{"t":"Skin Irritation Guide – Redness, Dryness & Sensitivity Spots","c":10,"en":"Handling the common skin reactions: redness, dryness and sensitive spots.","nl":"Omgaan met de gebruikelijke huidreacties: roodheid, droogheid en gevoelige plekken."},{"t":"Skin preparation & patch testing","c":10,"en":"Clean, residue-free skin and a small test spot to lower the risks.","nl":"Schone huid zonder resten en een klein testplekje om risico's te verkleinen."},{"t":"Storage & handling","c":10,"en":"Keep DMSO away from heat and contamination, and label it clearly.","nl":"Bewaar DMSO weg van warmte en vervuiling en label het duidelijk."},{"t":"What DMSO Is – Properties & How It Works","c":10,"en":"An introduction to what DMSO is and why it behaves uniquely with water and the skin.","nl":"Introductie over wat DMSO is en waarom het zich bijzonder gedraagt met water en de huid."},{"t":"When to Avoid DMSO – Contraindications & Cautions","c":10,"en":"Lists situations where DMSO should be paused or avoided, such as damaged skin or recent procedures.","nl":"Somt situaties op waarin je DMSO beter stopt of vermijdt, zoals beschadigde huid of een recente ingreep."}]};